import sys

def is_canonical(n, coins):
    def greedy_coins(amount):
        count = 0
        for coin in reversed(coins):
            while amount >= coin:
                amount -= coin
                count += 1
        return count

    def min_coins(amount):
        dp = [float('inf')] * (amount + 1)
        dp[0] = 0
        for i in range(1, amount + 1):
            for coin in coins:
                if i >= coin:
                    dp[i] = min(dp[i], dp[i - coin] + 1)
        return dp[amount]

    max_check = coins[-1] + coins[-2]
    for x in range(1, max_check):
        if min_coins(x) < greedy_coins(x):
            return "non-canonical"
    return "canonical"

input = sys.stdin.read().split()
n = int(input[0])
coins = list(map(int, input[1:n+1]))
print(is_canonical(n, coins))
